sys_script_include.script:
var GrievanceHashEngine = Class.create()

GrievanceHashEngine.prototype = {
    initialize: function () {},

    /**
     * Generates a SHA-256 hash of the supplied payload.
     *
     * @param {string} payload - the text to hash
     * @return {string} lowercase hex-encoded SHA-256 digest, or an empty
     *                  string when the payload is empty
     */
    generateHash: function (payload) {
        if (payload === null || payload === undefined) {
            return ''
        }

        var text = '' + payload

        if (!text) {
            return ''
        }

        return new GlideDigest().getSHA256Hex(text)
    },

    type: 'GrievanceHashEngine',
}
